{
  "schemaVersion": 1,
  "command": "task-bundle",
  "subcommands": [
    "check",
    "build",
    "publish"
  ],
  "description": "Check, build and publish complete TypeBox Task Bundles.",
  "usage": "pguide task-bundle check author <task.build.yaml> | check artifact <directory> | build <task.build.yaml> | publish <directory> [--ipfs-rpc <url>]",
  "sections": [
    {
      "title": "Commands",
      "lines": [
        "  check author <file>     Compile trusted author input in memory; no output writes or network publishing.",
        "  check artifact <dir>    Validate exact manifest, Schema and UnixFS CID; never evaluate author code.",
        "  build <file>            Replace only managed output after complete validation; no network publishing.",
        "  publish <dir>           Import and pin an already built artifact; never build or execute Tasks."
      ]
    },
    {
      "title": "Configuration",
      "lines": [
        "  --ipfs-rpc overrides task-bundle.ipfsRpc from pguide user -> nearest project config.jsonc.",
        "  No default node, daemon startup or global configuration writes. Only publish uses RPC."
      ]
    },
    {
      "title": "Trust",
      "lines": [
        "  Author check/build evaluate the contract module as trusted local code, not in a sandbox.",
        "  include is a build rule, not a subcommand. Old bundles without an exact manifest must be rebuilt."
      ]
    }
  ],
  "optionDetails": [
    {
      "name": "--ipfs-rpc",
      "description": "overrides task-bundle.ipfsRpc from pguide user -> nearest project config.jsonc."
    }
  ],
  "globalOptions": [
    {
      "name": "--cwd",
      "argument": "<directory>",
      "description": "Configuration and relative-path context",
      "default": "current directory"
    },
    {
      "name": "--format",
      "argument": "<format>",
      "description": "markdown | json",
      "default": "markdown",
      "values": [
        "markdown",
        "json"
      ]
    },
    {
      "name": "--color",
      "argument": "<mode>",
      "description": "auto | always | never",
      "default": "auto",
      "values": [
        "auto",
        "always",
        "never"
      ]
    },
    {
      "name": "--log-level",
      "argument": "<level>",
      "description": "error | warn | info | debug",
      "default": "warn",
      "values": [
        "error",
        "warn",
        "info",
        "debug"
      ]
    },
    {
      "name": "--help",
      "description": "Show help without executing the command"
    },
    {
      "name": "--version",
      "description": "Show command version"
    }
  ],
  "constraints": [],
  "examples": []
}

